import sys, json
sys.path.insert(0, 'scripts')
import identity_check as ic
ic.validate_url = lambda url, resolver=None: None
class Headers:
    def get(self, key):
        return 'text/html'
class Resp:
    def __init__(self):
        self.headers = Headers()
        self.sent = False
    def __enter__(self):
        return self
    def __exit__(self, *a):
        return False
    def read(self, n):
        if self.sent:
            return b''
        self.sent = True
        return b'x' * (ic.MAX_FETCH_BYTES + 1)
class Opener:
    def open(self, req, timeout=None):
        return Resp()
try:
    ic.safe_open('https://example.com/', opener=Opener())
    print(json.dumps({'status': 'ok'}))
except ic.UnsafeUrl as exc:
    print(json.dumps({'status': 'unsafe', 'reason': exc.reason}))

